test("readme run-detail-analyzer.png", async ({ page }) => {
  await mockApi(page, { snapshotById: { 281: SNAPSHOT_COMPLETED } });
  await page.goto("/runs/281", { waitUntil: "networkidle" });
  // The analyzer column only (exclude the sibling "Sample efficiency" curve card).
  const card = page
    .locator('div:has-text("Analyzer reasoning"):not(:has-text("Sample efficiency"))')
    .first();
  await card.waitFor({ timeout: 15_000 });
  await card.scrollIntoViewIfNeeded();
  await page.waitForTimeout(400);
  await card.screenshot({ path: `${OUT}/run-detail-analyzer.png` });
});
